(window.TIMELINE_TRANSLATIONS=window.TIMELINE_TRANSLATIONS||{})["ar"]={"qin-dynasty":{"id":"qin-dynasty","title":"سلالة تشين","summary":"غزت دولة تشين منافسيها الرئيسيين بقيادة ينغ تشنغ، الذي اتخذ اللقب الإمبراطوري تشين شي هوانغ. لم تدم السلالة سوى فترة قصيرة، لكن ممارساتها العسكرية والإدارية أثرت في إمبراطورية هان التي خلفتها.","began":"بلغت فتوحات تشين ذروتها بالتوحيد، وأعلن ينغ تشنغ نفسه إمبراطورًا.","ended":"انهارت السلالة في السنوات التي تلت وفاة تشين شي هوانغ، وتصارعت قوى متنافسة قبل أن تقيم هان الحكم الإمبراطوري.","why":"أنشأت إطارًا سياسيًا إمبراطوريًا كيّفته السلالات اللاحقة."},"confucius":{"id":"confucius","title":"كونفوشيوس يعلّم الحكم الأخلاقي","summary":"علّم كونفوشيوس خلال فترة الربيع والخريف. وشدد على السلوك الأخلاقي والمسؤوليات الأسرية والتعلم وواجب الحاكم في الحكم بالفضيلة. وأصبحت تعاليمه تقليدًا فكريًا كبيرًا، وجعلت الحكومات الإمبراطورية اللاحقة النصوص الكونفوشية محور التعليم الرسمي.","why":"شكّلت تعاليمه الأخلاق السياسية والتعليم والمثل الأسرية في أنحاء شرق آسيا."},"stonewall-riots":{"id":"stonewall-riots","title":"انتفاضة ستونوول","summary":"قاوم رواد حانة ستونوول إن في نيويورك ومؤيدوهم مداهمة للشرطة، أعقبتها مواجهات ومظاهرات أخرى. وأصبحت الانتفاضة نقطة مرجعية قوية لحركة متنامية ضد اضطهاد الأقليات الجنسية.","why":"ساعدت ستونوول في تنشيط حركة تحرير المثليين والتنظيم اللاحق لمجتمع الميم، من دون أن تكون أول عمل مقاومة."}};
